if (is_paused) return address(this).balance;
(uint256 c, , , , ,) = IAAVE(aave).getUserAccountData(address(this));
return c;
}
function getDebt() public view returns(uint256){
( , uint256 d, , , ,) = IAAVE(aave).getUserAccountData(address(this));
