emit EFRestart(_amount, getVirtualPrice());
}

event ActualLTVChanged(uint256 debt_before, uint256 collecteral_before, uint256 debt_after, uint256 collecteral_after);
function reduceActualLTV() public onlyOwner{
uint256 e = getDebt();
