uint256 e = getDebt();
uint256 st = getCollecteral();
require(e.safeMul(10000) > st.safeMul(mlr), "no need to reduce");
uint256 x = (e.safeMul(10000).safeSub(st.safeMul(mlr))).safeDiv(uint256(10000).safeSub(mlr));

