uint256 volume_before = getVolume();
if (volume_before < 1e9) {require(_amount >= 1e16, "Too small initial amount");}

uint256 fee_para = getFeeParam();
uint256 loan_amount = mlr.safeMul(_amount).safeDiv(fee_para.safeSub(mlr));
